/** The bundled zxcvbn name lists as structured entries (tagged "en"). */
export const BUILTIN_NAMES: BuiltinName[] = BUILTIN_NAMES_RAW
  .split("|")
  .filter(Boolean)
  .map((line) => {
    const tab = line.indexOf("\t");
    const name = tab >= 0 ? line.slice(0, tab) : line;
    const kind = tab >= 0 ? line.slice(tab + 1) : "surname";
    return { name, language: "en", kind: (kind === "female" || kind === "male" ? kind : "surname") as BuiltinNameKind };
  });
